public SyslogParser() {
        timestampCache = CacheBuilder.newBuilder().maximumSize(TS_CACHE_MAX).build(new CacheLoader<String, Long>() {

            @Override
            public Long load(String key) {
                return ZonedDateTime.parse(key, RFC5424_FORMAT.withZone(ZoneOffset.UTC))
                        .toInstant()
                        .toEpochMilli();
            }
        });
