void replay() throws IOException {
        Preconditions.checkState(!open, "Cannot replay after Log has been opened");

        lockExclusive();
        try {
            /*
             * First we are going to look through the data directories
             * and find all log files. We will store the highest file id
             * (at the end of the filename) we find and use that when we
             * create additional log files.
             *
             * Also store up the list of files so we can replay them later.
             */
            logger.info("Replay started");
            nextFileID.set(0);
            List<File> dataFiles = Lists.newArrayList();
            for (File logDir : logDirs) {
                for (File file : LogUtils.getLogs(logDir)) {
                    int id = LogUtils.getIDForFile(file);
                    dataFiles.add(file);
                    nextFileID.set(Math.max(nextFileID.get(), id));
                    idLogFileMap.put(
                            id,
                            LogFileFactory.getRandomReader(
                                    new File(logDir, PREFIX + id), encryptionKeyProvider, fsyncPerTransaction));
                }
            }
            logger.info("Found NextFileID " + nextFileID + ", from " + dataFiles);

            /*
             * sort the data files by file id so we can replay them by file id
             * which should approximately give us sequential events
             */
            LogUtils.sort(dataFiles);

            boolean shouldFastReplay = this.useFastReplay;
            /*
             * Read the checkpoint (in memory queue) from one of two alternating
             * locations. We will read the last one written to disk.
             */
            File checkpointFile = new File(checkpointDir, "checkpoint");
            if (shouldFastReplay) {
                if (checkpointFile.exists()) {
                    logger.debug("Disabling fast full replay because checkpoint " + "exists: " + checkpointFile);
                    shouldFastReplay = false;
                } else {
                    logger.debug("Not disabling fast full replay because checkpoint " + " does not exist: "
                            + checkpointFile);
                }
            }
            File inflightTakesFile = new File(checkpointDir, "inflighttakes");
            File inflightPutsFile = new File(checkpointDir, "inflightputs");
            File queueSetDir = new File(checkpointDir, QUEUE_SET);
            EventQueueBackingStore backingStore = null;

            try {
                backingStore = EventQueueBackingStoreFactory.get(
                        checkpointFile,
                        backupCheckpointDir,
                        queueCapacity,
                        channelNameDescriptor,
                        channelCounter,
                        true,
                        this.useDualCheckpoints,
                        this.compressBackupCheckpoint);
                queue = new FlumeEventQueue(backingStore, inflightTakesFile, inflightPutsFile, queueSetDir);
                logger.info("Last Checkpoint " + new Date(checkpointFile.lastModified()) + ", queue depth = "
                        + queue.getSize());

                /*
                 * We now have everything we need to actually replay the log files
                 * the queue, the timestamp the queue was written to disk, and
                 * the list of data files.
                 *
                 * This will throw if and only if checkpoint file was fine,
                 * but the inflights were not. If the checkpoint was bad, the backing
                 * store factory would have thrown.
                 */
                doReplay(queue, dataFiles, encryptionKeyProvider, shouldFastReplay);
            } catch (BadCheckpointException ex) {
                // Close the discarded queue and backing store and drop all references to them:
                // the checkpoint mapping is only released when the buffer is garbage collected,
                // and the deletion below cannot succeed on Windows until then.
                if (queue != null) {
                    try {
                        queue.close();
                    } catch (Exception closeEx) {
                        ex.addSuppressed(closeEx);
                    }
                    queue = null;
                } else if (backingStore != null) {
                    try {
                        backingStore.close();
                    } catch (Exception closeEx) {
                        ex.addSuppressed(closeEx);
                    }
                }
                backupRestored = false;
                if (useDualCheckpoints) {
                    logger.warn(
                            "Checkpoint may not have completed successfully. "
                                    + "Restoring checkpoint and starting up.",
                            ex);
                    if (EventQueueBackingStoreFile.backupExists(backupCheckpointDir)) {
                        backupRestored = EventQueueBackingStoreFile.restoreBackup(checkpointDir, backupCheckpointDir);
                    }
                }
                if (!backupRestored) {
                    logger.warn(
                            "Checkpoint may not have completed successfully. "
                                    + "Forcing full replay, this may take a while.",
                            ex);
                    if (!Serialization.deleteAllFiles(checkpointDir, EXCLUDES)) {
                        throw new IOException("Could not delete files in checkpoint "
                                + "directory to recover from a corrupt or incomplete checkpoint");
                    }
                }
                backingStore = EventQueueBackingStoreFactory.get(
                        checkpointFile,
                        backupCheckpointDir,
                        queueCapacity,
                        channelNameDescriptor,
                        channelCounter,
                        true,
                        useDualCheckpoints,
                        compressBackupCheckpoint);
                queue = new FlumeEventQueue(backingStore, inflightTakesFile, inflightPutsFile, queueSetDir);
                // If the checkpoint was deleted due to BadCheckpointException, then
                // trigger fast replay if the channel is configured to.
                shouldFastReplay = this.useFastReplay;
                doReplay(queue, dataFiles, encryptionKeyProvider, shouldFastReplay);
                if (!shouldFastReplay) {
                    didFullReplayDueToBadCheckpointException = true;
                }
            }

            for (int index = 0; index < logDirs.length; index++) {
                logger.info("Rolling " + logDirs[index]);
                roll(index);
            }

            /*
             * Now that we have replayed, write the current queue to disk
             */
            writeCheckpoint(true);

            open = true;
        } catch (Exception ex) {
            logger.error("Failed to initialize Log on " + channelNameDescriptor, ex);
            if (ex instanceof IOException) {
                throw (IOException) ex;
            }
            Throwables.propagate(ex);
        } finally {
            unlockExclusive();
        }
    }

public Event extractEvent(ByteBuf in) {

        /* for protocol debugging
        ByteBuffer bb = in.toByteBuffer();
        int remaining = bb.remaining();
        byte[] buf = new byte[remaining];
        bb.get(buf);
        HexDump.dump(buf, 0, System.out, 0);
        */

        byte b = 0;
        Event e = null;
        boolean doneReading = false;

        while (!doneReading && in.isReadable()) {
            b = in.readByte();
            switch (m) {
                case START:
                    if (b == '<') {
                        baos.write(b);
                        m = Mode.PRIO;
                    } else if (b == '\n') {
                        // If the character is \n, it was because the last event was exactly
                        // as long  as the maximum size allowed and
                        // the only remaining character was the delimiter - '\n', or
                        // multiple delimiters were sent in a row.
                        // Just ignore it, and move forward, don't change the mode.
                        // This is a no-op, just ignore it.
                        logger.debug("Delimiter found while in START mode, ignoring..");

                    } else {
                        isBadEvent = true;
                        baos.write(b);
                        // Bad event, just dump everything as if it is data.
                        m = Mode.DATA;
                    }
                    break;
                case PRIO:
                    baos.write(b);
                    if (b == '>') {
                        if (prio.length() == 0) {
                            isBadEvent = true;
                        }
                        m = Mode.DATA;
                    } else {
                        char ch = (char) b;
                        prio.append(ch);
                        // Priority is max 3 digits per both RFC 3164 and 5424
                        // With this check there is basically no danger of
                        // boas.size() exceeding this.maxSize before getting to the
                        // DATA state where this is actually checked
                        if (!Character.isDigit(ch) || prio.length() > 3) {
                            isBadEvent = true;
                            // If we hit a bad priority, just write as if everything is data.
                            m = Mode.DATA;
                        }
                    }
                    break;
                case DATA:
                    // TCP syslog entries are separated by '\n'
                    if (b == '\n') {
                        e = buildEvent();
                        doneReading = true;
                    } else {
                        baos.write(b);
                    }
                    if (baos.size() == this.maxSize && !doneReading) {
                        isIncompleteEvent = true;
                        e = buildEvent();
                        doneReading = true;
                    }
                    break;
            }
        }

        // UDP doesn't send a newline, so just use what we received
        if (e == null && isUdp) {
            doneReading = true;
            e = buildEvent();
        }

        return e;
    }

